package com.onlinemedic.service;
import com.onlinemedic.dao.UserDao;import com.onlinemedic.util.PasswordUtil;import java.math.BigDecimal;import java.sql.SQLException;import java.util.*;import java.util.regex.Pattern;
public class AdminService{
 private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");private final UserDao users=new UserDao();
 public long createDoctor(long actorId,String name,String email,String phone,String password,String specialization,String qualification,String registration,int experience,BigDecimal fee,String about,String clinic)throws SQLException{return createDoctor(actorId,name,email,phone,password,specialization,qualification,registration,experience,fee,about,clinic,null);}
 public long createDoctor(long actorId,String name,String email,String phone,String password,String specialization,String qualification,String registration,int experience,BigDecimal fee,String about,String clinic,String profileImage)throws SQLException{
  name=required(name,2,120,"Enter a valid doctor name.");email=required(email,5,190,"Enter an email address.");if(!EMAIL.matcher(email).matches())throw new IllegalArgumentException("Enter a valid doctor email.");specialization=required(specialization,2,100,"Enter a speciality.");qualification=required(qualification,2,160,"Enter the doctor's qualification.");registration=required(registration,2,80,"Enter the medical registration number.");phone=phone==null?"":phone.trim();if(phone.length()>30)throw new IllegalArgumentException("Phone number is too long.");if(password==null||password.length()<10||password.length()>128||!password.matches(".*[A-Za-z].*")||!password.matches(".*\\d.*"))throw new IllegalArgumentException("Set a password of at least 10 characters with a letter and number.");if(experience<0||experience>70||fee==null||fee.signum()<0||fee.compareTo(new BigDecimal("100000"))>0)throw new IllegalArgumentException("Check the experience and consultation fee values.");about=about==null?"":about.trim();clinic=clinic==null?"":clinic.trim();if(about.length()>1200||clinic.length()>180)throw new IllegalArgumentException("About or clinic details are too long.");
  try{return users.registerDoctor(actorId,name,email,phone,PasswordUtil.hash(password),specialization,qualification,registration,experience,fee,about,clinic,profileImage);}catch(SQLException e){if(e.getSQLState()!=null&&e.getSQLState().startsWith("23"))throw new IllegalArgumentException("That doctor email or registration information already exists.");throw e;}
 }
 public String updateDoctor(long actorId,long doctorId,String name,String email,String phone,boolean active,String newPassword,String specialization,String qualification,String registration,int experience,BigDecimal fee,String about,String clinic,String profileImage)throws SQLException{
  name=required(name,2,120,"Enter a valid doctor name.");email=required(email,5,190,"Enter an email address.");if(!EMAIL.matcher(email).matches())throw new IllegalArgumentException("Enter a valid doctor email.");specialization=required(specialization,2,100,"Enter a speciality.");qualification=required(qualification,2,160,"Enter the doctor's qualification.");registration=registration==null?"":registration.trim();if(registration.length()>80)throw new IllegalArgumentException("Registration number is too long.");phone=phone==null?"":phone.trim();if(phone.length()>30)throw new IllegalArgumentException("Phone number is too long.");if(experience<0||experience>70||fee==null||fee.signum()<0||fee.compareTo(new BigDecimal("100000"))>0)throw new IllegalArgumentException("Check the experience and consultation fee values.");about=about==null?"":about.trim();clinic=clinic==null?"":clinic.trim();if(about.length()>1200||clinic.length()>180)throw new IllegalArgumentException("About or clinic details are too long.");
  String passwordHash=null;if(newPassword!=null&&!newPassword.isBlank()){String value=newPassword.trim();if(value.length()<10||value.length()>128||!value.matches(".*[A-Za-z].*")||!value.matches(".*\\d.*"))throw new IllegalArgumentException("Set a new password of at least 10 characters with a letter and number, or leave it blank to keep the current password.");passwordHash=PasswordUtil.hash(value);}
  try{return users.updateDoctorByAdmin(actorId,doctorId,name,email,phone,active,passwordHash,specialization,qualification,registration.isBlank()?null:registration,experience,fee,about,clinic,profileImage);}catch(SQLException e){if(e.getSQLState()!=null&&e.getSQLState().startsWith("23"))throw new IllegalArgumentException("That email or registration information is already in use.");throw e;}
 }
 public long createStaff(long actorId,String name,String email,String phone,String password,String role,String credential,String location)throws SQLException{return createStaff(actorId,name,email,phone,password,role,credential,location,null);}
 public long createStaff(long actorId,String name,String email,String phone,String password,String role,String credential,String location,String pharmacyImage)throws SQLException{
  name=required(name,2,120,"Enter the staff member's name.");email=required(email,5,190,"Enter an email address.");if(!EMAIL.matcher(email).matches())throw new IllegalArgumentException("Enter a valid email address.");if(!"PHARMACIST".equals(role)&&!"DELIVERY".equals(role))throw new IllegalArgumentException("Choose pharmacist or delivery staff.");phone=phone==null?"":phone.trim();credential=credential==null?"":credential.trim();location=location==null?"":location.trim();if(phone.length()>30||credential.length()>100||location.length()>180)throw new IllegalArgumentException("One of the staff details is too long.");if("DELIVERY".equals(role)&&phone.replaceAll("\\D","").length()<7)throw new IllegalArgumentException("Enter a delivery staff contact number with at least 7 digits.");if(password==null||password.length()<10||password.length()>128||!password.matches(".*[A-Za-z].*")||!password.matches(".*\\d.*"))throw new IllegalArgumentException("Set a password of at least 10 characters with a letter and number.");if(credential.length()<2)throw new IllegalArgumentException("Enter the license or vehicle number.");if("PHARMACIST".equals(role)&&location.length()<2)throw new IllegalArgumentException("Enter the pharmacy name.");
  try{return users.registerStaff(actorId,name,email,phone,PasswordUtil.hash(password),role,credential,location,pharmacyImage);}catch(SQLException e){if(e.getSQLState()!=null&&e.getSQLState().startsWith("23"))throw new IllegalArgumentException("That email or staff credential already exists.");throw e;}
 }
 public void updateStaff(long actorId,long staffId,String role,String name,String email,String phone,boolean active,String newPassword,String credential,String location)throws SQLException{
  name=required(name,2,120,"Enter a valid staff name.");email=required(email,5,190,"Enter an email address.");if(!EMAIL.matcher(email).matches())throw new IllegalArgumentException("Enter a valid email address.");phone=phone==null?"":phone.trim();credential=credential==null?"":credential.trim();location=location==null?"":location.trim();
  if(phone.length()>30||credential.length()>100||location.length()>180)throw new IllegalArgumentException("One of the staff details is too long.");
  if("DELIVERY".equals(role)&&phone.replaceAll("\\D","").length()<7)throw new IllegalArgumentException("Delivery staff must have a phone number with at least 7 digits.");
  if(credential.length()<2)throw new IllegalArgumentException("Enter the license or vehicle number.");
  if("PHARMACIST".equals(role)&&location.length()<2)throw new IllegalArgumentException("Enter the pharmacy name.");
  String hash=null;if(newPassword!=null&&!newPassword.isBlank()){String value=newPassword.trim();if(value.length()<10||value.length()>128||!value.matches(".*[A-Za-z].*")||!value.matches(".*\\d.*"))throw new IllegalArgumentException("Set a new password of at least 10 characters with a letter and number, or leave it blank to keep the current password.");hash=PasswordUtil.hash(value);}
  try{users.updateStaffByAdmin(actorId,staffId,role,name,email,phone.isBlank()?null:phone,active,hash,credential,"PHARMACIST".equals(role)?location:null);}catch(SQLException e){if(e.getSQLState()!=null&&e.getSQLState().startsWith("23"))throw new IllegalArgumentException("That email or staff credential is already in use.");throw e;}
 }
 public List<Map<String,Object>> staffList()throws SQLException{return users.adminStaffList();}
 private String required(String value,int min,int max,String error){if(value==null||value.trim().length()<min||value.trim().length()>max)throw new IllegalArgumentException(error);return value.trim();}
}
